attrs = ['A','B','C','D','E']

def closure(attr_set, fds):
    result = set(attr_set)
    changed = True
    while changed:
        changed = False
        for lhs, rhs in fds:
            if lhs.issubset(result):
                new = rhs - result
                if new:
                    result.update(new)
                    changed = True
    return frozenset(result)

